using System;
using System.IO;
using System.Linq;
using Newtonsoft.Json.Linq;
using HollowCraft.Standalone;

internal static partial class Program
{
    private static void LauncherSettings(string root,string assets) {
        string cfg=Path.Combine(root,"launcher-settings.json"),storage=Path.Combine(root,"launcher-save");
        File.WriteAllText(cfg,new JObject{["schema"]=1,["keepInventory"]=false,["automaticWater"]=true,["waterReturnTicks"]=60}.ToString());
        using(var game=new NativeGame(storage,assets,cfg)){Send(game,"room","drop","scene","exactX",0,"exactY",1);Latest(game);int before=game.Inventory.Slots.Sum(s=>s.Count)+game.Inventory.Armor.Sum(s=>s.Count);Send(game,"room","drop","damage","amount",40,"kind","fall");var state=Latest(game);Check(game.Inventory.Slots.All(s=>s.Empty)&&game.Inventory.Armor.All(s=>s.Empty),"Death-drop rule empties the real backpack and worn armor");var room=CurrentRoom(game);Check(room.Drops.Sum(s=>(int)s["count"])==before,"Death drops conserve inventory quantities");int drops=room.Drops.Count;Send(game,"room","drop","respawn");Latest(game);Check(game.Inventory.Slots.All(s=>s.Empty),"Respawn cannot regenerate the starting kit after a death drop");Send(game,"room","drop","damage","amount",40,"kind","fall");Latest(game);Check(room.Drops.Count==drops,"Repeated death cannot issue the same kit twice");}
        using(var game=new NativeGame(Path.Combine(root,"keep-save"),assets)){Send(game,"room","keep","scene","exactX",0,"exactY",1);Latest(game);Send(game,"room","keep","damage","amount",40,"kind","fall");Latest(game);Check(!game.Inventory.Hand.Empty&&CurrentRoom(game).Drops.Count==0,"Default keep-inventory behavior remains compatible");}
        var kit=new NativeInventory();kit.Starter();for(int i=0;i<36;i++)kit.Slots[i]=new NativeStack();for(int i=0;i<4;i++)kit.Armor[i]=new NativeStack();kit.Slots[0]=NativeStack.New("diamond_pickaxe");kit.Slots[0].Data["efficiency"]=3;
        var config=new JObject{["schema"]=1,["keepInventory"]=true,["loadoutRevision"]="kit-1",["applyLoadoutToExisting"]=false,["loadout"]=kit.Save()};File.WriteAllText(cfg,config.ToString());
        using(var game=new NativeGame(storage,assets,cfg)){Send(game,"room","custom","scene","exactX",0,"exactY",1);Latest(game);Check(game.Inventory.Hand.Id=="minecraft:diamond_pickaxe"&&NativeData.Enchantment(game.Inventory.Hand,"efficiency")==3&&game.Inventory.Armor.All(s=>s.Empty),"New campaigns receive exactly the selected kit including NBT and empty armor slots");game.Inventory.Slots[0]=NativeStack.New("cobblestone",2);}
        using(var game=new NativeGame(storage,assets,cfg)){Send(game,"room","custom","scene","exactX",0,"exactY",1);Latest(game);Check(game.Inventory.Hand.Id=="minecraft:cobblestone"&&game.Inventory.Hand.Count==2,"Starting-kit preferences do not silently replace an existing backpack");}
        config["applyLoadoutToExisting"]=true;config["loadoutRevision"]="kit-2";File.WriteAllText(cfg,config.ToString());
        using(var game=new NativeGame(storage,assets,cfg)){Send(game,"room","custom","scene","exactX",0,"exactY",1);Latest(game);Check(game.Inventory.Hand.Id=="minecraft:diamond_pickaxe","Explicit existing-save kit application replaces inventory");game.Inventory.Slots[0]=NativeStack.New("diamond",17);}
        using(var game=new NativeGame(storage,assets,cfg)){Send(game,"room","custom","scene","exactX",0,"exactY",1);Latest(game);Check(game.Inventory.Hand.Id=="minecraft:diamond"&&game.Inventory.Hand.Count==17,"A saved kit revision is applied only once per campaign");}
        File.WriteAllText(cfg,new JObject{["schema"]=1,["keepInventory"]=true,["automaticWater"]=true,["waterReturnTicks"]=60}.ToString());
        using(var game=new NativeGame(storage,assets,cfg)){Send(game,"room","water-rule","scene","exactX",.5,"exactY",1);Latest(game);Send(game,"room","water-rule","nativeLanding","landing",1,"x",.5,"y",1,"distance",12);var messages=Drain(game);Check(messages.Any(m=>(string)m["type"]=="landing"&&(string)m["kind"]=="water"),"Survival fall at exactly twelve blocks activates automatic water");Advance(game,40);Check(CurrentRoom(game).Blocks.Values.Any(c=>c["autoReturnAt"]!=null),"Configured delayed collection leaves water visible long enough");}
        using(var game=new NativeGame(storage,assets,cfg)){Send(game,"room","water-rule","scene","exactX",.5,"exactY",1);Latest(game);Advance(game,30);Check(!CurrentRoom(game).Blocks.Values.Any(c=>c["autoReturnAt"]!=null),"Automatic water collection survives a save and reload");}
        using(var game=new NativeGame(storage,assets,cfg)){Send(game,"room","slab-water","scene","exactX",.5,"exactY",1.5);Latest(game);Put(CurrentRoom(game),0,1,"oak_slab");Send(game,"room","slab-water","nativeLanding","landing",1,"x",.5,"y",1.5,"distance",12);Drain(game);Check((bool?)CurrentRoom(game).Blocks["0:1"]["waterlogged"]==true,"Automatic landing water works on an occupied half-slab cell");Advance(game,61);Check((string)CurrentRoom(game).Blocks["0:1"]["id"]=="minecraft:oak_slab"&&(bool?)CurrentRoom(game).Blocks["0:1"]["waterlogged"]==false,"Collecting automatic water preserves the original slab");}
        using(var game=new NativeGame(storage,assets,cfg)){Send(game,"Tutorial_01","intro-rule","scene","exactX",.5,"exactY",1,"intro",false);Latest(game);Send(game,"Tutorial_01","intro-rule","nativeLanding","landing",1,"x",.5,"y",1,"distance",2);Check(Drain(game).Any(m=>(string)m["type"]=="landing"&&(string)m["kind"]=="water"),"Fresh tutorial opening retains its special first landing even if the intro flag was missed");}
        using(var game=new NativeGame(storage,assets,cfg)){Send(game,"room","hero-rule","scene","exactX",.5,"exactY",1);Latest(game);Send(game,"room","hero-rule","mode","mode","creative");Latest(game);Send(game,"room","hero-rule","nativeLanding","landing",1,"x",.5,"y",1,"distance",13);Check(Drain(game).Any(m=>(string)m["type"]=="landing"&&(string)m["kind"]=="hero")&&CurrentRoom(game).Blocks.Count==0,"Creative high fall uses superhero landing rather than automatic water");}
        File.WriteAllText(cfg,new JObject{["schema"]=1,["automaticWater"]=false}.ToString());
        using(var game=new NativeGame(storage,assets,cfg)){Send(game,"room","disabled-water","scene","exactX",.5,"exactY",1);Latest(game);Send(game,"room","disabled-water","nativeLanding","landing",1,"x",.5,"y",1,"distance",12);var state=Latest(game);Check((double)state["stats"]["health"]<20&&CurrentRoom(game).Blocks.Count==0,"Disabling automatic water restores ordinary falling damage");}
    }
}
